files.content:
:root {
  --bg: #1a1c2c;
  --card: #2b2d42;
  --text: #f0f0f0;
  --accent: #ffcd75;
  --accent-dark: #e0a800;
  --muted: #a0a0b0;
  --border: #4a4d6a;
  --focus: #75d1ff;
  --pressed: #c49a00;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: linear-gradient(45deg, #22243a 25%, transparent 25%, transparent 75%, #22243a 75%),
                    linear-gradient(45deg, #22243a 25%, transparent 25%, transparent 75%, #22243a 75%);
  background-size: 8px 8px;
  background-position: 0 0, 4px 4px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 rgba(0,0,0,0.5);
  padding: 24px;
  width: 100%;
  max-width: 400px;
  image-rendering: pixelated;
}

h1 {
  margin: 0 0 4px;
  font-size: 2rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 #000;
}

.subtitle {
  margin: 0 0 24px;
  color: var(--muted);
  font-size: 0.95rem;
}

.field {
  margin-bottom: 20px;
  border: none;
  padding: 0;
}

label, legend {
  display: block;
  margin-bottom: 8px;
  font-weight: 600;
  font-size: 1rem;
  color: var(--text);
}

input[type="number"] {
  width: 100%;
  padding: 12px;
  font-size: 1.25rem;
  font-family: inherit;
  background: #1e2030;
  border: 3px solid var(--border);
  color: var(--text);
  outline: none;
  border-radius: 0;
}

input[type="number"]:focus {
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(117, 209, 255, 0.3);
}

input[type="number"]::placeholder {
  color: var(--muted);
}

.tip-buttons {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.tip-btn {
  flex: 1 1 0;
  min-width: 64px;
  padding: 12px 8px;
  font-size: 1.1rem;
  font-family: inherit;
  font-weight: 700;
  background: #3a3d5a;
  color: var(--text);
  border: 3px solid var(--border);
  cursor: pointer;
  transition: background 0.1s, transform 0.05s;
  border-radius: 0;
}

.tip-btn:hover {
  background: #4a4d6a;
  border-color: var(--accent);
}

.tip-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.tip-btn[aria-pressed="true"] {
  background: var(--accent);
  color: #1a1c2c;
  border-color: var(--accent-dark);
}

.tip-btn[aria-pressed="true"]:hover {
  background: var(--accent-dark);
}

.tip-btn:active {
  transform: translate(2px, 2px);
  background: var(--pressed);
  border-color: var(--pressed);
}

.results {
  margin-top: 24px;
  border-top: 3px dashed var(--border);
  padding-top: 20px;
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 1.1rem;
  margin-bottom: 12px;
}

.result-row.total {
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--accent);
}

.amount {
  font-variant-numeric: tabular-nums;
  font-weight: 700;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.6rem;
  }
  .tip-btn {
    font-size: 1rem;
    padding: 10px 4px;
  }
}

(function () {
  'use strict';

  const billInput = document.getElementById('bill');
  const peopleInput = document.getElementById('people');
  const tipButtons = document.querySelectorAll('.tip-btn');
  const tipPerPersonEl = document.getElementById('tipPerPerson');
  const totalPerPersonEl = document.getElementById('totalPerPerson');

  let selectedTip = 0;

  function formatCurrency(value) {
    return '$' + value.toFixed(2);
  }

  function calculate() {
    const bill = parseFloat(billInput.value);
    const people = parseInt(peopleInput.value, 10);

    if (isNaN(bill) || bill < 0 || isNaN(people) || people < 1) {
      tipPerPersonEl.textContent = formatCurrency(0);
      totalPerPersonEl.textContent = formatCurrency(0);
      return;
    }

    const tipAmount = bill * (selectedTip / 100);
    const total = bill + tipAmount;
    const tipPerPerson = tipAmount / people;
    const totalPerPerson = total / people;

    tipPerPersonEl.textContent = formatCurrency(tipPerPerson);
    totalPerPersonEl.textContent = formatCurrency(totalPerPerson);
  }

  function selectTip(button) {
    tipButtons.forEach(function (btn) {
      btn.setAttribute('aria-pressed', btn === button ? 'true' : 'false');
    });
    selectedTip = parseFloat(button.getAttribute('data-tip'));
    calculate();
  }

  tipButtons.forEach(function (button) {
    button.addEventListener('click', function () {
      selectTip(button);
    });
  });

  billInput.addEventListener('input', calculate);
  peopleInput.addEventListener('input', calculate);

  // Initialize with 15% selected
  const defaultButton = Array.from(tipButtons).find(function (btn) {
    return btn.getAttribute('data-tip') === '15';
  });
  if (defaultButton) {
    selectTip(defaultButton);
  }
})();
